    "versets_count": 123,
    "theme": "La galerie des prophètes face à leurs peuples — Noé et le déluge, Hūd et les ʿĀd, Ṣāliḥ et la chamelle, Abraham, Loth, Shuʿayb, Moïse — et l'ordre redoutable : « Tiens-toi droit comme il t'a été commandé »",
    "note_pedagogique": "La sourate dont le Prophète dit : « Hūd et ses sœurs m'ont blanchi les cheveux » — à cause du verset 112 : istaqim kamā umirta, « tiens-toi droit comme il t'a été commandé ». Elle déroule les récits des prophètes avec une intensité dramatique unique : le dialogue de Noé avec son fils englouti par les flots en est le sommet pathétique.",
