      "ar": "إِنَّ الَّذِينَ ءَامَنُواْ وَعَمِلُواْ الصَّـٰلِحَٰتِ وَأَخْبَتُواْ إِلَىٰ رَبِّهِمْ أُوْلَـٰئِكَ أَصْحَٰبُ الْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ",
      "translit": "Inna lladhīna āmanū waʿamilū ṣ-ṣāliḥāti waʾakhbatū ilā rabbihim ūlāʾika aṣḥābu l-jannati hum fīhā khālidūn",
