      "ar": "وَامْرَأَتُهُ قَائِمَةٌ فَضَحِكَتْ فَبَشَّرْنَٰهَا بِإِسْحَٰقَ وَمِن وَرَاءِ إِسْحَٰقَ يَعْقُوبَ",
      "translit": "Wamraʾatuhū qāʾimatun faḍaḥikat fabashsharnāhā biʾisḥāqa wamin warāʾi isḥāqa yaʿqūb",
