    "declic_frequence": "istaqāma (se tenir droit, être constant, racine ق-و-م) porte au v.112 l'ordre qui fit blanchir les cheveux du Prophète : fa-staqim kamā umirta — « tiens-toi droit comme il t'a été commandé ». L'istiqāma est la rectitude maintenue : ni zèle excessif ni relâchement, la ligne droite tenue jour après jour, sans dévier « ni transgresser ». C'est plus exigeant qu'un exploit ponctuel : la constance dans la durée, la fidélité sans éclat mais sans faille. La sourate entière — chaque prophète tenant bon face à son peuple — illustre cette verticalité de l'âme."
